114	        cadence = assumption.cadence, starts_on = assumption.starts_on, schedule_anchor_on = assumption.schedule_anchor_on, ends_on = assumption.ends_on,
115	        source = assumption.source, confidence = assumption.confidence, confirmed = assumption.confirmed,
116	        recurring_evidence_eligible = coalesce(assumption.recurring_evidence_eligible,false),
117	        enabled = assumption.enabled, removed_at = assumption.removed_at where id = event_row.entity_id;
118	    end if;
119	  else
